<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\DcrInitialAccessToken\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use DateTime;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\Retrieve\DcrInitialAccessTokenRetrieveUsecase;
use Civi\Lughauth\Shared\Security\AesCypherService;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\Retrieve\DcrInitialAccessTokenRetrieveResult;

class DcrInitialAccessTokenRetrieveController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly DcrInitialAccessTokenRetrieveUsecase $retrieveUsecase,
        private readonly AesCypherService $cypherService,
    ) {
    }
    #[OA\Get(
        path: "/api/access/dcr-initial-access-tokens{uid}",
        tags: ["Dcr initial access token"],
        description:"Create",
        parameters: [
               new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
          ],
        responses: [
              new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/DcrInitialAccessTokenApiDTO")),
              new OA\Response(response: 404, description: "Not found"),
          ]
    )]
    public function retrieve(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Retrieve Dcr initial access token");
        $span = $this->startSpan("Retrieve Dcr initial access token");
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $result = $this->retrieveUsecase->retrieve($uid);
            $value = $this->mapDcrInitialAccessToken($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapDcrInitialAccessToken(ServerRequestInterface $request, DcrInitialAccessTokenRetrieveResult $value): DcrInitialAccessTokenApiDTO
    {
        $this->logDebug("Map entity to output dto for Dcr initial access token");
        $span = $this->startSpan("Map entity to output dto for Dcr initial access token");
        try {
            $tenant = $value->getTenant();
            $dto = new DcrInitialAccessTokenApiDTO();
            $dto->uid = $value->getUid();
            $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
            $dto->description = $value->getDescription();
            $dto->tokenHash = '******';
            $dto->expiresAt = $value->getExpiresAt()?->format(DateTime::ATOM);
            $dto->maxUses = $value->getMaxUses();
            $dto->uses = $value->getUses();
            $dto->allowedGrantTypes = $value->getAllowedGrantTypes();
            $dto->revokedAt = $value->getRevokedAt()?->format(DateTime::ATOM);
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
